"""Deterministic synthetic log dataset generator for demos, verification, and scale testing."""

from __future__ import annotations

import gzip
import json
import random
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta, timezone
from pathlib import Path
from typing import Any


@dataclass
class GeneratedDatasetManifest:
    """Manifest of exact expected counts generated by the deterministic generator."""

    output_dir: Path
    seed: int
    files_created: list[str]
    expected_total_events: int
    expected_error_events: int
    expected_warning_events: int
    expected_info_events: int
    expected_debug_events: int
    expected_malformed_lines: int
    expected_missing_timestamp_events: int
    expected_duplicate_overlaps: int
    expected_anomaly_windows: list[str]
    expected_category_counts: dict[str, int]

    def to_dict(self) -> dict[str, Any]:
        return {
            "output_dir": str(self.output_dir),
            "seed": self.seed,
            "files_created": self.files_created,
            "expected_total_events": self.expected_total_events,
            "expected_error_events": self.expected_error_events,
            "expected_warning_events": self.expected_warning_events,
            "expected_info_events": self.expected_info_events,
            "expected_debug_events": self.expected_debug_events,
            "expected_malformed_lines": self.expected_malformed_lines,
            "expected_missing_timestamp_events": self.expected_missing_timestamp_events,
            "expected_duplicate_overlaps": self.expected_duplicate_overlaps,
            "expected_anomaly_windows": self.expected_anomaly_windows,
            "expected_category_counts": self.expected_category_counts,
        }


def generate_demo_dataset(
    output_dir: str | Path,
    seed: int = 42,
    include_spikes: bool = True,
) -> GeneratedDatasetManifest:
    """Generate a realistic multi-file, multi-format log dataset with known ground-truth counts.

    Timeline covers 24 five-minute windows from 2026-10-16T08:00:00Z to 2026-10-16T10:00:00Z.
    - Window 10 (08:50:00Z - 08:55:00Z): Database failure spike (34 errors -> combined threshold + statistical alert)
    - Window 17 (09:25:00Z - 09:30:00Z): API timeout spike (20 errors -> statistical anomaly alert)
    """
    rng = random.Random(seed)
    out_path = Path(output_dir)
    out_path.mkdir(parents=True, exist_ok=True)

    base_start = datetime(2026, 10, 16, 8, 0, 0, tzinfo=UTC)
    tz_ist = timezone(timedelta(hours=5, minutes=30))
    tz_edt = timezone(timedelta(hours=-4))

    app_log_rot2_lines: list[str] = []  # 08:00 - 08:40 (.log.2.gz)
    app_log_rot1_lines: list[str] = []  # 08:40 - 09:20 (.log.1)
    app_log_curr_lines: list[str] = []  # 09:20 - 10:00 (.log)
    auth_jsonl_lines: list[str] = []
    payment_iso_lines: list[str] = []
    nginx_error_lines: list[str] = []
    worker_syslog_lines: list[str] = []

    expected_info = 0
    expected_debug = 0
    expected_warning = 0
    expected_error = 0
    expected_malformed = 0
    expected_missing_ts = 0
    expected_duplicates = 0
    cat_counts: dict[str, int] = {}

    def _inc_cat(cat_name: str) -> None:
        cat_counts[cat_name] = cat_counts.get(cat_name, 0) + 1

    def _append_app_line(win_idx: int, line_str: str) -> None:
        if win_idx < 8:
            app_log_rot2_lines.append(line_str)
        elif win_idx < 16:
            app_log_rot1_lines.append(line_str)
        else:
            app_log_curr_lines.append(line_str)

    # Generate events across 24 five-minute windows (08:00 to 10:00 UTC)
    req_counter = 1000
    for win_idx in range(24):
        win_start = base_start + timedelta(minutes=5 * win_idx)

        # 1. Normal operational traffic in each window across services
        for i in range(8):
            ts = win_start + timedelta(seconds=i * 32 + rng.randint(1, 10))
            req_counter += 1
            ts_py = ts.strftime("%Y-%m-%d %H:%M:%S,") + f"{rng.randint(100, 999):03d}"
            if i % 4 == 0:
                _append_app_line(
                    win_idx,
                    f"{ts_py} - catalog.api - DEBUG - [req-{req_counter}] (handlers.py:54) Cache lookup hit for product_id={100 + i} in 2.4ms",
                )
                expected_debug += 1
            else:
                _append_app_line(
                    win_idx,
                    f"{ts_py} - catalog.api - INFO - [req-{req_counter}] (handlers.py:88) Processed GET /v1/products/{200 + i} HTTP 200 in {12 + i}ms",
                )
                expected_info += 1

        # Normal JSONL auth traffic (2 INFO per window)
        for j in range(2):
            ts = win_start + timedelta(seconds=45 + j * 90)
            req_counter += 1
            rec = {
                "timestamp": ts.astimezone(tz_ist).isoformat(),
                "level": "INFO",
                "service": "auth-service",
                "logger": "auth.oauth",
                "request_id": f"req-{req_counter}",
                "file": "oauth_controller.py",
                "line": 64,
                "message": f"Session token verified for user_id={5000 + win_idx * 10 + j} sess_99a8b7c6d5",
            }
            auth_jsonl_lines.append(json.dumps(rec))
            expected_info += 1

        # Normal ISO payment traffic (2 INFO + 1 WARNING every 2 windows)
        for k in range(2):
            ts = win_start + timedelta(seconds=20 + k * 110)
            req_counter += 1
            ts_iso = ts.astimezone(tz_edt).isoformat()
            payment_iso_lines.append(
                f"{ts_iso} [INFO] [payment-service] [payment.ledger] (ledger.py:112) [req-{req_counter}] Recorded transaction tx-{9000 + win_idx * 10 + k} for customer@example.org"
            )
            expected_info += 1

        if win_idx % 2 == 0:
            ts_w = win_start + timedelta(seconds=150)
            req_counter += 1
            payment_iso_lines.append(
                f"{ts_w.isoformat().replace('+00:00', 'Z')} [WARNING] [payment-service] [payment.retry] (gateway.py:140) [req-{req_counter}] Slow upstream response from gateway 10.20.4.18:443 took 1850ms"
            )
            expected_warning += 1

        # Baseline background errors (2 errors per normal window so median baseline is 2.0)
        # Error 1 in every window: Auth failure in JSONL
        ts_e1 = win_start + timedelta(seconds=75)
        req_counter += 1
        auth_err_rec = {
            "timestamp": ts_e1.isoformat().replace("+00:00", "Z"),
            "level": "ERROR",
            "service": "auth-service",
            "logger": "auth.jwt",
            "request_id": f"req-{req_counter}",
            "exception": "AuthenticationError",
            "error_code": "HTTP_401",
            "file": "jwt_verifier.py",
            "line": 128,
            "message": (
                f"Authentication failed: JWT signature verification failed for user email=intruder{win_idx}@example.com "
                f"with token Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJ1c2VyIn0.dummysig123456"
            ),
        }
        auth_jsonl_lines.append(json.dumps(auth_err_rec))
        expected_error += 1
        _inc_cat("Authentication & Authorization Failures")

        # Error 2 in every even window: File system / permission error in worker syslog,
        # and in every odd window: Application KeyError with multiline Python traceback
        ts_e2 = win_start + timedelta(seconds=195)
        req_counter += 1
        if win_idx % 2 == 0:
            ts_sys = ts_e2.strftime("%b %d %H:%M:%S")
            worker_syslog_lines.append(
                f"<35>{ts_sys} prod-worker-01 report-exporter[{2400 + win_idx}]: [ERROR] [req-{req_counter}] "
                f"(exporter.py:91) PermissionError: [Errno 13] EACCES: Permission denied writing '/var/spool/exports/batch_{win_idx}.csv'"
            )
            expected_error += 1
            _inc_cat("File System & Permission Errors")
        else:
            ts_py = ts_e2.strftime("%Y-%m-%d %H:%M:%S,410")
            tb_block = (
                f"{ts_py} - catalog.api - ERROR - [req-{req_counter}] (pricing.py:203) "
                f"Unhandled exception calculating discount for cart_id={7000 + win_idx} at 0x7f8a1c00{win_idx:02x}0\n"
                f"Traceback (most recent call last):\n"
                f'  File "/srv/app/catalog/handlers.py", line 142, in compute_cart\n'
                f"    total = apply_promo_tier(cart, tier_map)\n"
                f'  File "/srv/app/catalog/pricing.py", line 203, in apply_promo_tier\n'
                f'    multiplier = tier_map["enterprise_tier"]\n'
                f"KeyError: 'enterprise_tier'"
            )
            _append_app_line(win_idx, tb_block)
            expected_error += 1
            _inc_cat("Application Exceptions")

        # Periodic secondary failures in select windows to ensure rich category coverage
        if win_idx in (3, 7, 14, 21):
            ts_net = win_start + timedelta(seconds=210)
            ts_ng = ts_net.strftime("%Y/%m/%d %H:%M:%S")
            nginx_error_lines.append(
                f"{ts_ng} [error] 1842#1842: *{8800 + win_idx} connect() failed (111: ECONNREFUSED: Connection refused) "
                f"while connecting to upstream, client: 10.0.12.{win_idx}, server: api.internal, "
                f'request: "POST /v1/checkout HTTP/1.1", upstream: "http://10.0.4.22:8080/v1/checkout"'
            )
            expected_error += 1
            _inc_cat("Network & Connection Failures")

        if win_idx in (5, 13):
            ts_res = win_start + timedelta(seconds=230)
            req_counter += 1
            worker_syslog_lines.append(
                f"<34>1 {ts_res.isoformat().replace('+00:00', 'Z')} prod-worker-02 ml-scorer 3190 OOM99 - "
                f"[CRITICAL] [req-{req_counter}] (scorer.py:310) MemoryError: ENOMEM Out of memory allocating tensor buffer of 2048MB"
            )
            expected_error += 1
            _inc_cat("Resource Exhaustion")

        if win_idx in (6, 19):
            ts_cfg = win_start + timedelta(seconds=240)
            req_counter += 1
            payment_iso_lines.append(
                f"{ts_cfg.isoformat().replace('+00:00', 'Z')} [ERROR] [payment-service] [payment.config] "
                f"(settings.py:49) [req-{req_counter}] ConfigurationError: Missing required environment variable STRIPE_WEBHOOK_SECRET "
                f"(fallback api_key=sk_live_998877665544332211)"
            )
            expected_error += 1
            _inc_cat("Configuration Errors")

        if win_idx in (4, 15, 22):
            ts_http = win_start + timedelta(seconds=250)
            req_counter += 1
            payment_iso_lines.append(
                f"{ts_http.isoformat().replace('+00:00', 'Z')} [ERROR] [payment-service] [payment.webhook] "
                f"(webhook.py:175) [req-{req_counter}] HTTPError: Webhook delivery failed with HTTP 502 Bad Gateway from partner endpoint"
            )
            expected_error += 1
            _inc_cat("API / HTTP Failures")

        # ---------------------------------------------------------------------
        # SPIKE 1: Window 10 (08:50:00Z - 08:55:00Z)
        # Massive Database Connection Pool Exhaustion & Refused Burst (+32 errors -> 34 total in window)
        # ---------------------------------------------------------------------
        if include_spikes and win_idx == 10:
            for s_idx in range(32):
                ts_sp1 = win_start + timedelta(seconds=5 + s_idx * 8)
                req_counter += 1
                ts_py = ts_sp1.strftime("%Y-%m-%d %H:%M:%S,") + f"{(s_idx * 17) % 1000:03d}"
                tb_db = (
                    f"{ts_py} - catalog.db - CRITICAL - [req-{req_counter}] (db_pool.py:118) "
                    f"Database connection failed for postgres://db_admin:SuperSecretDbPass123!@10.0.8.50:5432/prod_catalog "
                    f"(SQLSTATE[08006] attempt {s_idx + 1})\n"
                    f"Traceback (most recent call last):\n"
                    f'  File "/srv/app/catalog/db_pool.py", line 118, in acquire_connection\n'
                    f"    conn = psycopg2.connect(dsn, connect_timeout=5)\n"
                    f"psycopg2.OperationalError: FATAL: remaining connection slots are reserved for non-replication superuser connections"
                )
                _append_app_line(win_idx, tb_db)
                expected_error += 1
                _inc_cat("Database Errors")

        # ---------------------------------------------------------------------
        # SPIKE 2: Window 17 (09:25:00Z - 09:30:00Z)
        # Upstream Payment API Gateway Timeout Burst (+18 errors -> 20 total in window)
        # Below absolute_threshold=25, but triggers statistical_anomaly alert!
        # ---------------------------------------------------------------------
        if include_spikes and win_idx == 17:
            for s_idx in range(18):
                ts_sp2 = win_start + timedelta(seconds=8 + s_idx * 14)
                req_counter += 1
                payment_iso_lines.append(
                    f"{ts_sp2.isoformat().replace('+00:00', 'Z')} [ERROR] [payment-service] [payment.gateway] "
                    f"(gateway.py:219) [req-{req_counter}] ReadTimeout: ETIMEDOUT Upstream payment processor timed out "
                    f"after 5000ms for order_id=550e8400-e29b-41d4-a716-4466554400{s_idx:02d} at 10.20.4.18:443"
                )
                expected_error += 1
                _inc_cat("Timeout Errors")

    # Add 1 record with missing timestamp (Python basicConfig style) to app_server.log
    app_log_curr_lines.append(
        "ERROR:catalog.LegacySync:Legacy sync task encountered an uncategorized checksum mismatch on shard 4"
    )
    expected_error += 1
    expected_missing_ts += 1
    _inc_cat("Uncategorized Errors")

    # Add 2 intentionally malformed lines (1 in app_server.log, 1 in auth_service.jsonl)
    app_log_curr_lines.insert(
        5, "@@@ CORRUPTED_STREAM_FRAME_WITHOUT_TIMESTAMP_OR_SEVERITY_HEADER @@@"
    )
    auth_jsonl_lines.insert(
        4, '{"timestamp": "2026-10-16T08:12:00Z", "level": "ERROR", "broken_json": '
    )
    expected_malformed = 2

    # Add 2 duplicate overlapping records at rotation boundary (end of .log.1 repeated at start of .log)
    overlap_lines = app_log_rot1_lines[-2:]
    app_log_curr_lines = list(overlap_lines) + app_log_curr_lines
    expected_duplicates = len(overlap_lines)

    # Write all log files
    rot2_path = out_path / "app_server.log.2.gz"
    with gzip.open(rot2_path, "wt", encoding="utf-8") as gz_fh:
        gz_fh.write("\n".join(app_log_rot2_lines) + "\n")

    rot1_path = out_path / "app_server.log.1"
    rot1_path.write_text("\n".join(app_log_rot1_lines) + "\n", encoding="utf-8")

    curr_path = out_path / "app_server.log"
    curr_path.write_text("\n".join(app_log_curr_lines) + "\n", encoding="utf-8")

    auth_path = out_path / "auth_service.jsonl"
    auth_path.write_text("\n".join(auth_jsonl_lines) + "\n", encoding="utf-8")

    pay_path = out_path / "payment_iso.log"
    pay_path.write_text("\n".join(payment_iso_lines) + "\n", encoding="utf-8")

    nginx_path = out_path / "gateway_nginx_error.log"
    nginx_path.write_text("\n".join(nginx_error_lines) + "\n", encoding="utf-8")

    syslog_path = out_path / "worker_syslog.log"
    syslog_path.write_text("\n".join(worker_syslog_lines) + "\n", encoding="utf-8")

    files_created = [
        rot2_path.name,
        rot1_path.name,
        curr_path.name,
        auth_path.name,
        pay_path.name,
        nginx_path.name,
        syslog_path.name,
    ]

    total_events = expected_info + expected_debug + expected_warning + expected_error
    anomaly_windows = (
        ["2026-10-16T08:50:00+00:00", "2026-10-16T09:25:00+00:00"] if include_spikes else []
    )

    return GeneratedDatasetManifest(
        output_dir=out_path,
        seed=seed,
        files_created=files_created,
        expected_total_events=total_events,
        expected_error_events=expected_error,
        expected_warning_events=expected_warning,
        expected_info_events=expected_info,
        expected_debug_events=expected_debug,
        expected_malformed_lines=expected_malformed,
        expected_missing_timestamp_events=expected_missing_ts,
        expected_duplicate_overlaps=expected_duplicates,
        expected_anomaly_windows=anomaly_windows,
        expected_category_counts=cat_counts,
    )


def generate_scale_log_file(
    file_path: str | Path,
    event_count: int = 100_000,
    seed: int = 99,
) -> Path:
    """Generate a single synthetic log file with `event_count` events for performance testing."""
    rng = random.Random(seed)
    target = Path(file_path)
    target.parent.mkdir(parents=True, exist_ok=True)
    base_ts = datetime(2026, 10, 16, 0, 0, 0, tzinfo=UTC)

    templates = [
        ("INFO", "catalog.api", "(handlers.py:88) Processed GET /v1/items/{num} HTTP 200 in 14ms"),
        ("INFO", "auth.service", "(login.py:42) User session validated for user_id={num}"),
        ("DEBUG", "worker.queue", "(runner.py:31) Heartbeat check ok for worker-{num}"),
        (
            "WARNING",
            "payment.retry",
            "(gateway.py:140) Slow response from upstream took 1420ms [req-{num}]",
        ),
        (
            "ERROR",
            "catalog.db",
            "(db_pool.py:118) psycopg2.OperationalError: database connection refused on port 5432 [req-{num}]",
        ),
        (
            "ERROR",
            "payment.gateway",
            "(gateway.py:219) TimeoutError: ETIMEDOUT read timeout after 5000ms [req-{num}]",
        ),
    ]

    with target.open("w", encoding="utf-8") as fh:
        for i in range(event_count):
            ts = base_ts + timedelta(milliseconds=i * 250)
            ts_str = ts.strftime("%Y-%m-%d %H:%M:%S,") + f"{(i * 7) % 1000:03d}"
            # Roughly 90% INFO/DEBUG, 5% WARNING, 5% ERROR, plus a spike around i=50000..50500
            if 50000 <= i < 50400:
                sev, logger_name, msg_t = templates[4]
            else:
                pick = rng.random()
                if pick < 0.70:
                    sev, logger_name, msg_t = templates[0] if i % 2 == 0 else templates[1]
                elif pick < 0.90:
                    sev, logger_name, msg_t = templates[2]
                elif pick < 0.95:
                    sev, logger_name, msg_t = templates[3]
                else:
                    sev, logger_name, msg_t = templates[4] if i % 2 == 0 else templates[5]
            fh.write(f"{ts_str} - {logger_name} - {sev} - {msg_t.format(num=i)}\n")

    return target
